local language=GetCVar and lower(GetCVar("language.2") or "en") or "en"
S.language=translations[language] and language or "en"
function S.Text(key,...)
    local value=(translations[S.language] or translations.en)[key] or translations.en[key] or key
    if select("#",...)>0 then return format(value,...)end
    return value
end
